/* An actual paid-ready producer is preserved across native Clear -> unit A. */
#define main existing_combat_regression_main
#include "test_em_web_selection_combat.c"
#undef main
static void check(int okay,const char*why){if(!okay){fprintf(stderr,"FAIL %s %s\n",why,dune_web_actions_debug());exit(1);}}
static unsigned yard,unit,product,paid;
static void setup(void){reset();yard=dune_long(&em_cpu,0xc578);unsigned p=yard&65535;check(em_web_action_context().ready,"real paid-ready selected Yard");product=dune_word(&em_cpu,p+82);paid=em_cpu.ram[p+3];unit=0;for(unsigned a=0x1000;a<0x47c8;a+=140)if(em_web_action_live(0xff0000+a,0)&&em_cpu.ram[a+8]==dune_word(&em_cpu,0xc274)){unsigned tile=dune_word(&em_cpu,a+10)/256*64+dune_word(&em_cpu,a+12)/256,t=0x7d9c+tile*4;if((em_cpu.ram[t+2]&16)&&em_cpu.ram[t+3]==(a-0x1000)/140+1){unit=0xff0000+a;break;}}check(unit,"mapped own unit exists in actual paid fixture");}
static int tap_unit(void){return em_web_ready_yard_unit_tap(dune_word(&em_cpu,(unit&65535)+12)/8,dune_word(&em_cpu,(unit&65535)+10)/8);}
static void paid_unchanged(void){unsigned p=yard&65535;check((dune_word(&em_cpu,p+6)&0x2000)&&dune_word(&em_cpu,p+82)==product&&em_cpu.ram[p+3]==paid,"ready product and real paid allocation retained");check(!em_web_selection.placement_attempts&&!em_web_selection.placement_successes,"unit tap never tries placement or creates a building");}
int main(int argc,char**argv){if(argc!=2)return 2;FILE*f=fopen(argv[1],"rb");check(f&&fread(&baseline,sizeof baseline,1,f)==1,"actual paid-ready CPU snapshot");fclose(f);
 setup();check(tap_unit(),"short own-unit tap queues native clear then original A");check(em_host.dune_mouse.count==0&&em_web_selection.select_unit_after_clear,"no A precedes native deselection");uint64_t end=em_cpu.vdp.frames+120;while(!em_cpu.fault&&em_cpu.vdp.frames<end&&dune_long(&em_cpu,0xc25c)!=unit)step();check(dune_long(&em_cpu,0xc25c)==unit&&em_web_selection.native_clears==1&&native_a==1,"same original unit is selected through exactly one native A after clear");paid_unchanged();check(!tap_unit(),"an active unit retains contextual command priority");puts("PASS ready Yard -> own unit: one original clear+A, no placement, paid product unchanged");
 setup();check(tap_unit()&&dune_web_clear_selection(),"explicit Clear can cancel pending unit selection");end=em_cpu.vdp.frames+120;while(!em_cpu.fault&&em_cpu.vdp.frames<end&&em_web_selection.native_clears==0)step();check(!dune_long(&em_cpu,0xc25c)&&!dune_long(&em_cpu,0xc578)&&native_a==0,"cancelled deferred tap never selects later");paid_unchanged();puts("PASS explicit Clear cancels pending deferred unit tap");
 setup();unsigned p=yard&65535;check(em_web_placement_begin_world(dune_word(&em_cpu,p+12)/8+8,dune_word(&em_cpu,p+10)/8+8),"drag from the ready Yard remains native placement");check(dune_web_placement_active()&&!tap_unit(),"active placement drag cannot become an accidental unit tap");dune_web_placement_cancel();paid_unchanged();puts("PASS ready OK drag keeps native placement and product identity");return 0;}
